    /* F(n) has about n*0.209 decimal digits -> n*0.209/9 limbs (base 1e9). */
    size_t cap = (size_t)(n / 40) + 4;
    uint32_t *a = calloc(cap, sizeof *a), *b = calloc(cap, sizeof *b);
    if (!a || !b) { fprintf(stderr, "out of memory\n"); return 1; }
    size_t len = 1;
    a[0] = 0; b[0] = 1;                     /* a = F(0), b = F(1) */
    for (long i = 1; i < n; i++) {          /* (a, b) <- (b, a + b) */
        uint32_t carry = 0;
        for (size_t j = 0; j < len; j++) {
            uint32_t s = a[j] + b[j] + carry;
            carry = s >= BASE;
            if (carry) s -= BASE;
            a[j] = b[j];
            b[j] = s;
        }
        if (carry) { a[len] = 0; b[len] = carry; len++; }
    }
    printf("%u", b[len - 1]);
    for (size_t j = len - 1; j-- > 0;) printf("%09u", b[j]);
    printf("\n");
